module RecordedBattle::PlaybackHelper
  def self.pbGetOpponent(battle)
    return self.pbCreateTrainerInfo(battle[1]["opponent"])
  end

  def self.pbGetBattleBGM(battle)
    return self.pbGetTrainerBattleBGM(self.pbGetOpponent(battle))
  end

  def self.pbCreateTrainerInfo(trainer)
    return nil if !trainer
    ret = []
    trainer.each do |tr|
      if tr.length == 4   # Player
        t = Player.new(tr[1], tr[0])
        t.badges = tr[3]
      else   # NPCTrainer
        t = NPCTrainer.new(tr[1], tr[0])
        t.lose_text = tr[3] || "..."
        t.win_text = tr[4] || "..."
      end
      t.id = tr[2]
      ret.push(t)
    end
    return ret
  end
end

def initialize(scene, p1, p2, player, opponent)
  if p1.length == 0
    raise ArgumentError.new(_INTL("Party 1 has no Pokémon."))
  elsif p2.length == 0
    raise ArgumentError.new(_INTL("Party 2 has no Pokémon."))
  end
  @scene             = scene
  @peer              = Peer.new
  @field             = ActiveField.new    # Whole field (gravity/rooms)
  @sides             = [ActiveSide.new,   # Player's side
                        ActiveSide.new]   # Foe's side
  @positions         = []                 # Battler positions
  @battlers          = []
  @sideSizes         = [1, 1]   # Single battle, 1v1
  @backdrop          = ""
  @backdropBase      = nil
  @time              = 0
  @environment       = :None   # e.g. Tall grass, cave, still water
  @turnCount         = 0
  @decision          = 0
  @caughtPokemon     = []
  player   = [player] if !player.nil? && !player.is_a?(Array)
  opponent = [opponent] if !opponent.nil? && !opponent.is_a?(Array)
  @player            = player     # Array of Player/NPCTrainer objects, or nil
  @opponent          = opponent   # Array of NPCTrainer objects, or nil
  @items             = nil
  @ally_items        = nil        # Array of items held by ally. This is just used for Mega Evolution for now.
  @party1            = p1
  @party2            = p2
  @party1order       = Array.new(@party1.length) { |i| i }
  @party2order       = Array.new(@party2.length) { |i| i }
  @party1starts      = [0]
  @party2starts      = [0]
  @internalBattle    = true
  @debug             = false
  @canRun            = true
  @canLose           = false
  @canSwitch         = true
  @switchStyle       = true
  @showAnims         = true
  @controlPlayer     = false
  @expGain           = true
  @moneyGain         = true
  @disablePokeBalls  = false
  @sendToBoxes       = 1
  @rules             = {}
  @priority          = []
  @priorityTrickRoom = false
  @choices           = []
  @megaEvolution     = [
    [-1] * (@player ? @player.length : 1),
    [-1] * (@opponent ? @opponent.length : 1)
  ]
  @initialItems      = [
    Array.new(@party1.length) { |i| (@party1[i]) ? @party1[i].item_id : nil },
    Array.new(@party2.length) { |i| (@party2[i]) ? @party2[i].item_id : nil }
  ]
  @recycleItems      = [Array.new(@party1.length, nil),   Array.new(@party2.length, nil)]
  @belch             = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @battleBond        = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @corrosiveGas      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @usedInBattle      = [Array.new(@party1.length, false), Array.new(@party2.length, false)]
  @successStates     = []
  @lastMoveUsed      = nil
  @lastMoveUser      = -1
  @switching         = false
  @futureSight       = false
  @command_phase     = false
  @endOfRound        = false
  @moldBreaker       = false
  @runCommand        = 0
  @nextPickupUse     = 0
  @struggle          = Move::Struggle.new(self, nil)
  @mega_rings        = []
  GameData::Item.each { |item| @mega_rings.push(item.id) if item.has_flag?("MegaRing") }
  @battleAI          = AI.new(self)
end

#===============================================================================
# Trainer class for the player
#===============================================================================
class Player < Trainer
  # @return [Integer] the character ID of the player
  attr_reader   :character_ID
  # @return [Integer] the player's outfit
  attr_reader   :outfit
  # @return [Array<Boolean>] the player's Gym Badges (true if owned)
  attr_accessor :badges
  # @return [Integer] the player's money
  attr_reader   :money
  # @return [Integer] the player's Game Corner coins
  attr_reader   :coins
  # @return [Integer] the player's battle points
  attr_reader   :battle_points
  # @return [Integer] the player's soot
  attr_reader   :soot
  # @return [Pokedex] the player's Pokédex
  attr_reader   :pokedex
  # @return [Boolean] whether the Pokédex has been obtained
  attr_accessor :has_pokedex
  # @return [Boolean] whether the Pokégear has been obtained
  attr_accessor :has_pokegear
  # @return [Boolean] whether the player has running shoes (i.e. can run)
  attr_accessor :has_running_shoes
  # @return [Boolean] whether the player has an innate ability to access Pokémon storage
  attr_accessor :has_box_link
  # @return [Boolean] whether the creator of the Pokémon Storage System has been seen
  attr_accessor :seen_storage_creator
  # @return [Boolean] whether the effect of Exp All applies innately
  attr_accessor :has_exp_all
  # @return [Boolean] whether Mystery Gift can be used from the load screen
  attr_accessor :mystery_gift_unlocked
  # @return [Array<Array>] downloaded Mystery Gift data
  attr_accessor :mystery_gifts

  def initialize(name, trainer_type)
    super
    @character_ID          = 0
    @outfit                = 0
    @badges                = [false] * 8
    @money                 = GameData::Metadata.get.start_money
    @coins                 = 0
    @battle_points         = 0
    @soot                  = 0
    @pokedex               = Pokedex.new
    @has_pokedex           = false
    @has_pokegear          = false
    @has_running_shoes     = false
    @has_box_link          = false
    @seen_storage_creator  = false
    @has_exp_all           = false
    @mystery_gift_unlocked = false
    @mystery_gifts         = []
  end

  #=============================================================================

  def character_ID=(value)
    return if @character_ID == value
    @character_ID = value
    $game_player&.refresh_charset
  end

  def outfit=(value)
    return if @outfit == value
    @outfit = value
    $game_player&.refresh_charset
  end

  def trainer_type
    return GameData::PlayerMetadata.get(@character_ID || 1).trainer_type
  end

  # Sets the player's money. It can not exceed {Settings::MAX_MONEY}.
  # @param value [Integer] new money value
  def money=(value)
    validate value => Integer
    @money = value.clamp(0, Settings::MAX_MONEY)
  end

  # Sets the player's coins amount. It can not exceed {Settings::MAX_COINS}.
  # @param value [Integer] new coins value
  def coins=(value)
    validate value => Integer
    @coins = value.clamp(0, Settings::MAX_COINS)
  end

  # Sets the player's Battle Points amount. It can not exceed
  # {Settings::MAX_BATTLE_POINTS}.
  # @param value [Integer] new Battle Points value
  def battle_points=(value)
    validate value => Integer
    @battle_points = value.clamp(0, Settings::MAX_BATTLE_POINTS)
  end

  # Sets the player's soot amount. It can not exceed {Settings::MAX_SOOT}.
  # @param value [Integer] new soot value
  def soot=(value)
    validate value => Integer
    @soot = value.clamp(0, Settings::MAX_SOOT)
  end

  # @return [Integer] the number of Gym Badges owned by the player
  def badge_count
    return @badges.count { |badge| badge == true }
  end

  #=============================================================================

  # (see Pokedex#seen?)
  # Shorthand for +self.pokedex.seen?+.
  def seen?(species)
    return @pokedex.seen?(species)
  end

  # (see Pokedex#owned?)
  # Shorthand for +self.pokedex.owned?+.
  def owned?(species)
    return @pokedex.owned?(species)
  end
end
